tool.command:
#import re mkdir -p 'output_dir' && #set input_directory = 'input_directory' mkdir $input_directory &&
#for $input in $input_collection #set $fwd = re.sub('[^\w\-_\.]', '_', str($input.forward.name)) #set $rvs = re.sub('[^\w\-_\.]', '_', str($input.reverse.name)) ln -fs '${input.forward}' '$input_directory/$fwd' && ln -fs '${input.reverse}' '$input_directory/$rvs' && #end for
/opt/figaro/figaro/figaro.py --inputDirectory $input_directory --outputDirectory 'output_dir' --ampliconLength $ampliconLength --forwardPrimerLength $forwardPrimerLength --reversePrimerLength $reversePrimerLength #if $minimumOverlap: --minimumOverlap $minimumOverlap #end if #if $subsample: --subsample $subsample #end if #if $percentile: --percentile $percentile #end if 2>&1 | tee output_dir/figaro.log;
